// `s3` service (bundled S3 only): the network face of the bundled S3, at
// https://s3:8443. SeaweedFS runs in the `s3-storage` container without any
// network interface (network_mode: none), so none of its ports, the S3 gRPC
// port (IAM RPCs, unauthenticated without a filer signing key) included, can be
// reached from another container. This process terminates TLS with the
// certificate generated by install.sh and copies the decrypted bytes to the
// SeaweedFS S3 Unix socket, on a private tmpfs volume shared by the two
// containers only. Reads the TLS key as root, then drops to `node` (UID 1000,
// the UID of `seaweed`, owner of the socket). `--check` is the healthcheck.
import { readFileSync } from 'node:fs';
import net from 'node:net';
import tls from 'node:tls';
import { fileURLToPath } from 'node:url';

const PORT = 8443;
const SOCKET = '/run/reviewdesk-s3/s3.sock';
const CERT = '/etc/reviewdesk/certs/s3.pem';
const CA = '/etc/reviewdesk/certs/ca.pem';

export function startGateway({ host, port, key, cert, socketPath }) {
  const server = tls.createServer({ key, cert, minVersion: 'TLSv1.2' }, client => {
    const upstream = net.connect({ path: socketPath });
    client.on('error', () => upstream.destroy());
    upstream.on('error', () => client.destroy());
    // Graceful end both ways: destroy() would drop bytes not yet flushed.
    client.on('close', () => upstream.end());
    client.pipe(upstream).pipe(client);
  });
  // Plaintext or failed handshakes: drop the connection, keep serving.
  server.on('tlsClientError', (_error, socket) => socket.destroy());
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => resolve(server));
  });
}

// Healthcheck: the whole path (TLS with the name `s3` checked against the
// internal CA, gateway, socket, SeaweedFS) must answer /healthz with 200.
export function checkGateway({ port, ca, timeoutMs = 4000 }) {
  return new Promise(resolve => {
    const request = tls.connect({ host: '127.0.0.1', port, servername: 's3', ca, timeout: timeoutMs }, () => {
      request.write('GET /healthz HTTP/1.1\r\nHost: s3:8443\r\nConnection: close\r\n\r\n');
    });
    let head = '';
    request.on('data', chunk => { head += chunk; });
    request.on('end', () => resolve(/^HTTP\/1\.1 200 /.test(head)));
    request.on('timeout', () => { request.destroy(); resolve(false); });
    request.on('error', () => resolve(false));
  });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    process.exit(await checkGateway({ port: PORT, ca: readFileSync(CA) }) ? 0 : 1);
  }
  try {
    const key = readFileSync('/run/secrets/s3_tls_key');
    const cert = readFileSync(CERT);
    if (!key.includes('-----BEGIN PRIVATE KEY-----')) throw new Error('secret s3_tls_key invalide.');
    if (process.getuid?.() === 0) {
      process.setgroups([]);
      process.setgid('node');
      process.setuid('node');
    }
    await startGateway({ host: '0.0.0.0', port: PORT, key, cert, socketPath: SOCKET });
    process.stdout.write(`ReviewDesk : passerelle S3 HTTPS sur ${PORT} vers SeaweedFS (socket local).\n`);
  } catch (error) {
    process.stderr.write(`ReviewDesk (passerelle S3) : ${error.code === 'ENOENT' ? 'certificat ou secret manquant (relancez sh install.sh).' : error.message}\n`);
    process.exit(1);
  }
}
